class Solution {public long solve(int[] values){int n=values.length;int[] left=new int[n],right=new int[n];ArrayDeque<Integer> stack=new ArrayDeque<>();for(int i=0;i<n;i++){while(!stack.isEmpty()&&values[stack.peekLast()]>=values[i])stack.removeLast();left[i]=i-(stack.isEmpty()?-1:stack.peekLast());stack.addLast(i);}stack.clear();for(int i=n-1;i>=0;i--){while(!stack.isEmpty()&&values[stack.peekLast()]>values[i])stack.removeLast();right[i]=(stack.isEmpty()?n:stack.peekLast())-i;stack.addLast(i);}long total=0;for(int i=0;i<n;i++)total+=(long)values[i]*left[i]*right[i];return total;}}